import { useState } from 'react';
import { useTranslation } from '../hooks/useTranslation';
import type { TableInfo } from '../types';
import './Sidebar.css';

interface SidebarProps {
  tables: TableInfo[];
  onTableClick: (tableName: string) => void;
  onTableDelete: (tableName: string) => void;
  collapsed: boolean;
  onToggle: () => void;
}

export function Sidebar({ tables, onTableClick, onTableDelete, collapsed, onToggle }: SidebarProps) {
  const { t } = useTranslation();
  const [expanded, setExpanded] = useState<Record<string, boolean>>({});

  const toggle = (name: string) => {
    setExpanded((prev) => ({ ...prev, [name]: !prev[name] }));
  };

  return (
    <div className={`sidebar ${collapsed ? 'sidebar--collapsed' : ''}`}>
      <div className="sidebar__header">
        <h3 className="sidebar__title">{t('tablesHeader')}</h3>
        <button
          className="sidebar__collapse-toggle"
          onClick={onToggle}
          aria-label={collapsed ? t('expandSidebar') : t('collapseSidebar')}
        >
          <span className="sidebar__hamburger" />
        </button>
      </div>
      <div className="sidebar__content">
        {tables.length === 0 && (
          <p className="sidebar__empty">{t('noTables')}</p>
        )}
        <ul className="sidebar__list">
          {tables.map((table) => (
            <li key={table.name} className="sidebar__item">
              <div className="sidebar__table-header">
                <button
                  className="sidebar__toggle"
                  onClick={() => toggle(table.name)}
                >
                  {expanded[table.name] ? '\u25BC' : '\u25B6'}
                </button>
                <button
                  className="sidebar__table-name"
                  onClick={() => { onTableClick(table.name); toggle(table.name); }}
                >
                  {table.name}
                </button>
                <span className="sidebar__row-count">
                  {t('rowCount', { count: table.rowCount })}
                </span>
                <button
                  className="sidebar__delete"
                  onClick={(e) => {
                    e.stopPropagation();
                    onTableDelete(table.name);
                  }}
                  title={t('deleteTable', { name: table.name })}
                  aria-label={t('deleteTable', { name: table.name })}
                >
                  🗑
                </button>
              </div>
              {expanded[table.name] && (
                <ul className="sidebar__columns">
                  {table.columns.map((col) => (
                    <li key={col.name} className="sidebar__column">
                      <span className="sidebar__col-name">{col.name}</span>
                      <span className="sidebar__col-type">{col.type}</span>
                    </li>
                  ))}
                </ul>
              )}
            </li>
          ))}
        </ul>
      </div>
    </div>
  );
}

import os
import re

from fastapi import APIRouter, UploadFile, File, HTTPException

from app.config import MAX_TOTAL_SIZE_BYTES
from app.database import db, SUPPORTED_EXTENSIONS

router = APIRouter(prefix="/api", tags=["tables"])


def sanitize_table_name(filename: str) -> str:
    return filename


@router.get("/tables")
async def list_tables():
    return db.list_tables()


@router.post("/upload")
async def upload_file(file: UploadFile = File(...)):
    if not file.filename:
        raise HTTPException(status_code=400, detail="No filename provided")
    ext = os.path.splitext(file.filename)[1].lower()
    if ext not in SUPPORTED_EXTENSIONS:
        raise HTTPException(
            status_code=400,
            detail=f"Unsupported file format. Supported: {', '.join(sorted(SUPPORTED_EXTENSIONS))}"
        )
    content = await file.read()
    if len(content) > MAX_TOTAL_SIZE_BYTES:
        raise HTTPException(
            status_code=413,
            detail=f"File size exceeds the {MAX_TOTAL_SIZE_BYTES // (1024 * 1024)}MB limit"
        )
    table_name = sanitize_table_name(file.filename)
    try:
        results = db.load_file(content, file.filename, table_name)
    except ValueError as e:
        raise HTTPException(status_code=400, detail=str(e))
    except Exception as e:
        raise HTTPException(status_code=422, detail=f"Failed to process file: {e}")
    if len(results) == 1:
        return results[0]
    return results


@router.post("/upload/sample")
async def load_sample():
    """Load the built-in Titanic sample dataset."""
    from pathlib import Path

    csv_path = Path(__file__).resolve().parent.parent / "data" / "titanic.csv"
    if not csv_path.exists():
        raise HTTPException(status_code=404, detail="Sample dataset not found")
    return db.load_sample_data(str(csv_path), "titanic")


@router.delete("/tables/{table_name:path}")
async def drop_table(table_name: str):
    db.drop_table(table_name)
    return {"ok": True}

