  1→import { useState, useCallback, useEffect } from 'react';
  2→import { ThemeProvider } from './contexts/ThemeContext';
  3→import { useTheme } from './hooks/useTheme';
  4→import { LanguageProvider } from './contexts/LanguageContext';
  5→import { useTranslation } from './hooks/useTranslation';
  6→import { AgentProvider } from './contexts/AgentContext';
  7→import { ConfigProvider } from './contexts/ConfigContext';
  8→import { FileUpload } from './components/FileUpload';
  9→import { QueryEditor } from './components/QueryEditor';
 10→import { ResultsTable } from './components/ResultsTable';
 11→import { ResultMarkdown } from './components/ResultMarkdown';
 12→import { Sidebar } from './components/Sidebar';
 13→import { ErrorMessage } from './components/ErrorMessage';
 14→import { AgentPanel } from './components/AgentPanel';
 15→import type { TableInfo, QueryResult, LangfuseStatus } from './types';
 16→import './App.css';
 17→
 18→function AppContent({ tables, refreshTables, langfuseStatus }: { tables: TableInfo[]; refreshTables: () => Promise<void>; langfuseStatus: LangfuseStatus }) {
 19→  const { theme, toggleTheme } = useTheme();
 20→  const { language, setLanguage, t } = useTranslation();
 21→  const [queryResult, setQueryResult] = useState<QueryResult | null>(null);
 22→  const [error, setError] = useState<string | null>(null);
 23→  const [editorQuery, setEditorQuery] = useState<string | undefined>(
 24→    () => tables.length > 0 ? `SELECT * FROM "${tables[0].name}" LIMIT 100` : undefined
 25→  );
 26→  const [sidebarCollapsed, setSidebarCollapsed] = useState(() => window.innerWidth < 768);
 27→  const [agentOpen, setAgentOpen] = useState(true);
 28→
 29→  useEffect(() => {
 30→    document.title = t('appTitle');
 31→  }, [t]);
 32→
 33→  useEffect(() => {
 34→    if (tables.length === 0) {
 35→      setQueryResult(null);
 36→      setError(null);
 37→      setEditorQuery(undefined);
 38→    }
 39→  }, [tables]);
 40→
 41→  const handleAgentToggle = () => {
 42→    setAgentOpen((prev) => !prev);
 43→  };
 44→
 45→  const handleLoadSample = useCallback(async () => {
 46→    setError(null);
 47→    try {
 48→      const response = await fetch('/api/upload/sample', { method: 'POST' });
 49→      if (!response.ok) throw new Error('Failed to load sample dataset');
 50→      await refreshTables();
 51→      setEditorQuery('SELECT * FROM "titanic" LIMIT 100');
 52→    } catch (e) {
 53→      setError(e instanceof Error ? e.message : 'Failed to load sample dataset');
 54→    }
 55→  }, [refreshTables]);
 56→
 57→  const handleFileUpload = useCallback(
 58→    async (files: File[]) => {
 59→      setError(null);
 60→      let lastName = '';
 61→      try {
 62→        for (const file of files) {
 63→          const formData = new FormData();
 64→          formData.append('file', file);
 65→          const response = await fetch('/api/upload', {
 66→            method: 'POST',
 67→            body: formData,
 68→          });
 69→          if (!response.ok) {
 70→            const errorData = await response.json();
 71→            throw new Error(errorData.detail || 'Failed to upload file');
 72→          }
 73→          const result = await response.json();
 74→          // Handle both single table and array of tables (Excel with multiple sheets)
 75→          if (Array.isArray(result)) {
 76→            lastName = result[result.length - 1]?.name || '';
 77→          } else {
 78→            lastName = result.name;
 79→          }
 80→        }
 81→        await refreshTables();
 82→        if (lastName) {
 83→          setEditorQuery(`SELECT * FROM "${lastName}" LIMIT 100`);
 84→        }
 85→      } catch (e) {
 86→        setError(e instanceof Error ? e.message : 'Failed to upload file');
 87→      }
 88→    },
 89→    [refreshTables]
 90→  );
 91→
 92→  const handleQueryExecute = useCallback(
 93→    async (sql: string) => {
 94→      setError(null);
 95→      setQueryResult(null);
 96→      try {
 97→        const start = performance.now();
 98→        const response = await fetch('/api/query', {
 99→          method: 'POST',
100→          headers: { 'Content-Type': 'application/json' },
101→          body: JSON.stringify({ sql }),
102→        });
103→        const elapsed = performance.now() - start;
104→
105→        if (!response.ok) {
106→          const errorData = await response.json();
107→          throw new Error(errorData.detail || 'Query execution failed');
108→        }
109→
110→        const result = await response.json();
111→        setQueryResult({
112→          columns: result.columns,
113→          rows: result.rows,
114→          rowCount: result.rowCount,
115→          executionTimeMs: elapsed,
116→          resultType: result.resultType,
117→        });
118→        await refreshTables();
119→      } catch (e) {
120→        setError(e instanceof Error ? e.message : 'Query execution failed');
121→      }
122→    },
123→    [refreshTables]
124→  );
125→
126→  const handleTableClick = useCallback((tableName: string) => {
127→    setEditorQuery(`SELECT * FROM "${tableName}" LIMIT 100`);
128→  }, []);
129→
130→  const handleTableDelete = useCallback(async (tableName: string) => {
131→    if (!confirm(t('deleteTableConfirm', { name: tableName }))) return;
132→    try {
133→      const response = await fetch(`/api/tables/${encodeURIComponent(tableName)}`, {
134→        method: 'DELETE',
135→      });
136→      if (!response.ok) throw new Error('Failed to delete table');
137→      await refreshTables();
138→    } catch (e) {
139→      setError(e instanceof Error ? e.message : 'Failed to delete table');
140→    }
141→  }, [refreshTables, t]);
142→
143→  const appClass = [
144→    'app',
145→    sidebarCollapsed ? 'app--sidebar-collapsed' : '',
146→  ].filter(Boolean).join(' ');
147→
148→  const themeIcon = theme === 'dark' ? (
149→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
150→      <circle cx="12" cy="12" r="5" />
151→      <line x1="12" y1="1" x2="12" y2="3" />
152→      <line x1="12" y1="21" x2="12" y2="23" />
153→      <line x1="4.22" y1="4.22" x2="5.64" y2="5.64" />
154→      <line x1="18.36" y1="18.36" x2="19.78" y2="19.78" />
155→      <line x1="1" y1="12" x2="3" y2="12" />
156→      <line x1="21" y1="12" x2="23" y2="12" />
157→      <line x1="4.22" y1="19.78" x2="5.64" y2="18.36" />
158→      <line x1="18.36" y1="5.64" x2="19.78" y2="4.22" />
159→    </svg>
160→  ) : (
161→    <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
162→      <path d="M21 12.79A9 9 0 1 1 11.21 3 7 7 0 0 0 21 12.79z" />
163→    </svg>
164→  );
165→
166→  return (
167→    <div className={appClass}>
168→      <div className="app__sidebar-wrapper">
169→        <Sidebar tables={tables} onTableClick={handleTableClick} onTableDelete={handleTableDelete} collapsed={sidebarCollapsed} onToggle={() => setSidebarCollapsed((prev) => !prev)} />
170→      </div>
171→      {agentOpen ? (
172→        <div className="app__agent-wrapper">
173→          <div className="app__header">
174→            <h1 className="app__title">{t('appTitle')}</h1>
175→            <div className="app__header-actions">
176→              <button
177→                className="app__lang-toggle"
178→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
179→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
180→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
181→              >
182→                {language === 'en' ? 'EN' : '中'}
183→              </button>
184→              <button
185→                className="app__theme-toggle"
186→                onClick={toggleTheme}
187→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
188→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
189→              >
190→                {themeIcon}
191→              </button>
192→              <button
193→                className="app__agent-toggle app__agent-toggle--active"
194→                onClick={handleAgentToggle}
195→              >
196→                {t('editorMode')}
197→              </button>
198→            </div>
199→          </div>
200→          <AgentPanel
201→            langfuseStatus={langfuseStatus}
202→            tables={tables}
203→            onUpload={handleFileUpload}
204→            onLoadSample={handleLoadSample}
205→          />
206→        </div>
207→      ) : (
208→        <div className="app__editor-wrapper">
209→          <div className="app__header">
210→            <h1 className="app__title">{t('appTitle')}</h1>
211→            <div className="app__header-actions">
212→              <button
213→                className="app__lang-toggle"
214→                onClick={() => setLanguage(language === 'en' ? 'zh-TW' : 'en')}
215→                aria-label={language === 'en' ? t('switchToZh') : t('switchToEn')}
216→                title={language === 'en' ? t('switchToZh') : t('switchToEn')}
217→              >
218→                {language === 'en' ? 'EN' : '中'}
219→              </button>
220→              <button
221→                className="app__theme-toggle"
222→                onClick={toggleTheme}
223→                aria-label={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
224→                title={theme === 'dark' ? t('switchToLight') : t('switchToDark')}
225→              >
226→                {themeIcon}
227→              </button>
228→              <button
229→                className="app__agent-toggle"
230→                onClick={handleAgentToggle}
231→              >
232→                {t('agentMode')}
233→              </button>
234→            </div>
235→          </div>
236→          <div className="app__mode-header">
237→            <span className="app__mode-title">{t('editorMode')}</span>
238→          </div>
239→          <main className="app__main">
240→            {tables.length === 0 ? (
241→              <div className="app__empty">
242→                <FileUpload onUpload={handleFileUpload} onLoadSample={handleLoadSample} />
243→              </div>
244→            ) : (
245→              <>
246→                <QueryEditor
247→                  onExecute={handleQueryExecute}
248→                  initialQuery={editorQuery}
249→                />
250→                {error && (
251→                  <ErrorMessage message={error} onDismiss={() => setError(null)} />
252→                )}
253→                {queryResult?.resultType === 'markdown' ? (
254→                  <ResultMarkdown result={queryResult} />
255→                ) : (
256→                  <ResultsTable result={queryResult} />
257→                )}
258→              </>
259→            )}
260→          </main>
261→        </div>
262→      )}
263→    </div>
264→  );
265→}
266→
267→export default function App() {
268→  const [tables, setTables] = useState<TableInfo[]>([]);
269→  const [loading, setLoading] = useState(true);
270→  const [error, setError] = useState<string | null>(null);
271→  const [langfuseStatus, setLangfuseStatus] = useState<LangfuseStatus>({ enabled: false, dashboardUrl: null });
272→
273→  const refreshTables = useCallback(async () => {
274→    try {
275→      const response = await fetch('/api/tables');
276→      if (!response.ok) throw new Error('Failed to fetch tables');
277→      const data = await response.json();
278→      setTables(data);
279→    } catch (e) {
280→      console.error('Failed to refresh tables:', e);
281→    }
282→  }, []);
283→
284→  useEffect(() => {
285→    (async () => {
286→      try {
287→        const response = await fetch('/api/health');
288→        if (!response.ok) throw new Error('Backend is not available');
289→        await refreshTables();
290→        try {
291→          const lfRes = await fetch('/api/langfuse/status');
292→          if (lfRes.ok) {
293→            setLangfuseStatus(await lfRes.json());
294→          }
295→        } catch {
296→          // Langfuse status fetch is non-critical
297→        }
298→      } catch (e) {
299→        setError(e instanceof Error ? e.message : 'Failed to connect to backend');
300→      } finally {
301→        setLoading(false);
302→      }
303→    })();
304→  }, [refreshTables]);
305→
306→  if (loading) {
307→    return <div className="app-loading">Connecting to backend...</div>;
308→  }
309→
310→  if (error) {
311→    return (
312→      <div className="app-error">Failed to connect: {error}</div>
313→    );
314→  }
315→
316→  return (
317→    <ConfigProvider>
318→      <LanguageProvider>
319→        <ThemeProvider>
320→          <AgentProvider refreshTables={refreshTables}>
321→            <AppContent tables={tables} refreshTables={refreshTables} langfuseStatus={langfuseStatus} />
322→          </AgentProvider>
323→        </ThemeProvider>
324→      </LanguageProvider>
325→    </ConfigProvider>
326→  );
