.sidebar {
  background: var(--color-bg-tertiary);
  border-right: 1px solid var(--color-border-medium);
  padding: 0;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  height: 100vh;
}

.sidebar--collapsed {
  border-right: 1px solid var(--color-border-medium);
  width: 44px;
  min-width: 44px;
}

.sidebar__header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 12px 16px;
  background: var(--color-bg-tertiary);
  border-bottom: 1px solid var(--color-border-medium);
  flex-shrink: 0;
  position: sticky;
  top: 0;
  z-index: 1;
}

.sidebar--collapsed .sidebar__header {
  justify-content: center;
  padding: 8px;
  border-bottom: none;
}

.sidebar__title {
  margin: 0;
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.5px;
  color: var(--color-text-muted);
}

.sidebar--collapsed .sidebar__title {
  display: none;
}

.sidebar__content {
  flex: 1;
  overflow-y: auto;
  padding: 12px 16px;
}

.sidebar--collapsed .sidebar__content {
  display: none;
}

.sidebar__collapse-toggle {
  background: none;
  border: none;
  cursor: pointer;
  width: 28px;
  height: 28px;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 4px;
  flex-shrink: 0;
}

.sidebar__collapse-toggle:hover {
  background: var(--color-bg-hover-strong);
}

.sidebar__hamburger {
  display: block;
  width: 16px;
  height: 2px;
  background: var(--color-text-muted);
  position: relative;
}

.sidebar__hamburger::before,
.sidebar__hamburger::after {
  content: '';
  display: block;
  width: 16px;
  height: 2px;
  background: var(--color-text-muted);
  position: absolute;
  left: 0;
}

.sidebar__hamburger::before {
  top: -5px;
}

.sidebar__hamburger::after {
  top: 5px;
}

.sidebar__empty {
  font-size: 13px;
  color: var(--color-text-faint);
}

.sidebar__list {
  list-style: none;
  padding: 0;
  margin: 0;
}

.sidebar__item {
  margin-bottom: 4px;
}

.sidebar__table-header {
  display: flex;
  align-items: center;
  gap: 4px;
  min-width: 0;
}

.sidebar__toggle {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 10px;
  padding: 2px 4px;
  color: var(--color-text-muted);
}

.sidebar__table-name {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 13px;
  font-weight: 600;
  color: var(--color-text-primary);
  padding: 2px 4px;
  border-radius: 3px;
  text-align: left;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  min-width: 0;
  flex: 1;
}

.sidebar__table-name:hover {
  background: var(--color-bg-hover-strong);
}

.sidebar__row-count {
  font-size: 11px;
  color: var(--color-text-faint);
  margin-left: auto;
}

.sidebar__delete {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 12px;
  padding: 2px 4px;
  border-radius: 3px;
  opacity: 0;
  transition: opacity 0.15s;
  line-height: 1;
}

.sidebar__delete:hover {
  background: var(--color-error-bg-subtle);
}

.sidebar__table-header:hover .sidebar__delete {
  opacity: 1;
}

.sidebar__columns {
  list-style: none;
  padding: 4px 0 4px 24px;
  margin: 0;
}

.sidebar__column {
  display: flex;
  justify-content: space-between;
  font-size: 12px;
  padding: 2px 0;
}

.sidebar__col-name {
  color: var(--color-text-primary);
}

.sidebar__col-type {
  color: var(--color-text-faint);
  font-style: italic;
}

